CREATE TABLE public.voorraad_artikel (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),vestiging text NOT NULL CHECK(vestiging IN ('West','Midsland')),naam text NOT NULL,tel_eenheid text NOT NULL,telrol text NOT NULL DEFAULT 'bediening' CHECK(telrol IN ('bediening','keuken')),bestelbuffer numeric NOT NULL DEFAULT 0,verbruiksopslag_pct numeric NOT NULL DEFAULT 0,opslagplekken jsonb NOT NULL,telmoment text NOT NULL DEFAULT 'voor_opening' CHECK(telmoment IN ('voor_opening','na_sluiting')),actief boolean NOT NULL DEFAULT true,notitie text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(vestiging,naam));
GRANT SELECT,INSERT,UPDATE ON public.voorraad_artikel TO authenticated; GRANT ALL ON public.voorraad_artikel TO service_role;
ALTER TABLE public.voorraad_artikel ENABLE ROW LEVEL SECURITY;
CREATE POLICY proef_lezen ON public.voorraad_artikel FOR SELECT TO authenticated USING(heeft_vestiging(auth.uid(),vestiging));
CREATE POLICY proef_owner ON public.voorraad_artikel FOR ALL TO authenticated USING(heeft_vestiging(auth.uid(),vestiging) AND (has_role(auth.uid(),'owner') OR has_role(auth.uid(),'admin'))) WITH CHECK(heeft_vestiging(auth.uid(),vestiging) AND (has_role(auth.uid(),'owner') OR has_role(auth.uid(),'admin')));
CREATE TABLE public.voorraad_ontvangst_koppeling(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),voorraad_artikel_id uuid NOT NULL REFERENCES public.voorraad_artikel(id),leverancier_naam text NOT NULL DEFAULT '%',naam_patroon text NOT NULL,uitsluit_patroon text,artikel_id uuid REFERENCES public.artikelen(id),factor numeric NOT NULL CHECK(factor>0),UNIQUE(voorraad_artikel_id,naam_patroon));
GRANT SELECT,INSERT,UPDATE ON public.voorraad_ontvangst_koppeling TO authenticated; GRANT ALL ON public.voorraad_ontvangst_koppeling TO service_role; ALTER TABLE public.voorraad_ontvangst_koppeling ENABLE ROW LEVEL SECURITY;
CREATE POLICY proef_lezen ON public.voorraad_ontvangst_koppeling FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.voorraad_artikel a WHERE a.id=voorraad_artikel_id AND heeft_vestiging(auth.uid(),a.vestiging)));
CREATE POLICY proef_owner ON public.voorraad_ontvangst_koppeling FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.voorraad_artikel a WHERE a.id=voorraad_artikel_id AND heeft_vestiging(auth.uid(),a.vestiging)) AND (has_role(auth.uid(),'owner') OR has_role(auth.uid(),'admin'))) WITH CHECK(EXISTS(SELECT 1 FROM public.voorraad_artikel a WHERE a.id=voorraad_artikel_id AND heeft_vestiging(auth.uid(),a.vestiging)) AND (has_role(auth.uid(),'owner') OR has_role(auth.uid(),'admin')));
CREATE TABLE public.voorraad_verbruik_koppeling(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),voorraad_artikel_id uuid NOT NULL REFERENCES public.voorraad_artikel(id),lightspeed_product_id text NOT NULL,factor numeric NOT NULL CHECK(factor>0),UNIQUE(voorraad_artikel_id,lightspeed_product_id));
GRANT SELECT,INSERT,UPDATE ON public.voorraad_verbruik_koppeling TO authenticated; GRANT ALL ON public.voorraad_verbruik_koppeling TO service_role; ALTER TABLE public.voorraad_verbruik_koppeling ENABLE ROW LEVEL SECURITY;
CREATE POLICY proef_lezen ON public.voorraad_verbruik_koppeling FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.voorraad_artikel a WHERE a.id=voorraad_artikel_id AND heeft_vestiging(auth.uid(),a.vestiging)));
CREATE POLICY proef_owner ON public.voorraad_verbruik_koppeling FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.voorraad_artikel a WHERE a.id=voorraad_artikel_id AND heeft_vestiging(auth.uid(),a.vestiging)) AND (has_role(auth.uid(),'owner') OR has_role(auth.uid(),'admin'))) WITH CHECK(EXISTS(SELECT 1 FROM public.voorraad_artikel a WHERE a.id=voorraad_artikel_id AND heeft_vestiging(auth.uid(),a.vestiging)) AND (has_role(auth.uid(),'owner') OR has_role(auth.uid(),'admin')));
CREATE TABLE public.voorraad_telling(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),voorraad_artikel_id uuid NOT NULL REFERENCES public.voorraad_artikel(id),datum date NOT NULL,moment text NOT NULL CHECK(moment IN ('voor_opening','na_sluiting')),per_plek jsonb NOT NULL,totaal numeric NOT NULL,berekend_op_moment numeric,hertelling_van uuid REFERENCES public.voorraad_telling(id),betrouwbaar boolean NOT NULL DEFAULT false,geteld_door uuid,geteld_op timestamptz NOT NULL DEFAULT now(),bron_ref text NOT NULL UNIQUE);
GRANT SELECT ON public.voorraad_telling TO authenticated; GRANT INSERT(id,voorraad_artikel_id,datum,moment,per_plek,totaal,hertelling_van,bron_ref) ON public.voorraad_telling TO authenticated; GRANT ALL ON public.voorraad_telling TO service_role; ALTER TABLE public.voorraad_telling ENABLE ROW LEVEL SECURITY;
CREATE POLICY proef_lezen ON public.voorraad_telling FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.voorraad_artikel a WHERE a.id=voorraad_artikel_id AND heeft_vestiging(auth.uid(),a.vestiging)));
CREATE POLICY proef_tellen ON public.voorraad_telling FOR INSERT TO authenticated WITH CHECK(EXISTS(SELECT 1 FROM public.voorraad_artikel a WHERE a.id=voorraad_artikel_id AND heeft_vestiging(auth.uid(),a.vestiging)));
CREATE TABLE public.voorraad_correctie(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),voorraad_artikel_id uuid NOT NULL REFERENCES public.voorraad_artikel(id),datum date NOT NULL,hoeveelheid numeric NOT NULL,soort text NOT NULL CHECK(soort IN ('transfer','breuk','uitval')),notitie text NOT NULL,bron_ref text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.voorraad_correctie TO authenticated; GRANT ALL ON public.voorraad_correctie TO service_role; ALTER TABLE public.voorraad_correctie ENABLE ROW LEVEL SECURITY;
CREATE POLICY proef_lezen ON public.voorraad_correctie FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.voorraad_artikel a WHERE a.id=voorraad_artikel_id AND heeft_vestiging(auth.uid(),a.vestiging)));
CREATE POLICY proef_owner ON public.voorraad_correctie FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.voorraad_artikel a WHERE a.id=voorraad_artikel_id AND heeft_vestiging(auth.uid(),a.vestiging)) AND (has_role(auth.uid(),'owner') OR has_role(auth.uid(),'admin'))) WITH CHECK(EXISTS(SELECT 1 FROM public.voorraad_artikel a WHERE a.id=voorraad_artikel_id AND heeft_vestiging(auth.uid(),a.vestiging)) AND (has_role(auth.uid(),'owner') OR has_role(auth.uid(),'admin')));
CREATE TABLE public.advies_log(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),vestiging text NOT NULL CHECK(vestiging IN ('West','Midsland')),datum date NOT NULL,leverdag date NOT NULL,artikel text NOT NULL,artikel_id uuid REFERENCES public.artikelen(id),voorraad_artikel_id uuid REFERENCES public.voorraad_artikel(id),advies numeric NOT NULL,eenheid text,gegevens jsonb NOT NULL DEFAULT '{}',methode_versie text,werkelijk_besteld numeric,later_verkocht numeric,later_geteld numeric,afwijking numeric,leerstatus text NOT NULL DEFAULT 'onvolledig',bijgewerkt_op timestamptz NOT NULL DEFAULT now(),UNIQUE NULLS NOT DISTINCT(vestiging,leverdag,artikel,methode_versie));
GRANT SELECT ON public.advies_log TO authenticated; GRANT ALL ON public.advies_log TO service_role; ALTER TABLE public.advies_log ENABLE ROW LEVEL SECURITY;
CREATE POLICY proef_lezen ON public.advies_log FOR SELECT TO authenticated USING(heeft_vestiging(auth.uid(),vestiging));
CREATE TABLE public.voorraad_periode(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),voorraad_artikel_id uuid NOT NULL REFERENCES public.voorraad_artikel(id),begin_telling_id uuid NOT NULL REFERENCES public.voorraad_telling(id),eind_telling_id uuid NOT NULL REFERENCES public.voorraad_telling(id),begindatum date NOT NULL,einddatum date NOT NULL,begin numeric NOT NULL,ontvangen numeric NOT NULL,correcties numeric NOT NULL,kassa numeric NOT NULL,eind numeric NOT NULL,onverklaard numeric NOT NULL,pct_van_kassa numeric,volledig boolean NOT NULL,bijgewerkt_op timestamptz NOT NULL DEFAULT now(),UNIQUE(voorraad_artikel_id,begin_telling_id));
GRANT SELECT ON public.voorraad_periode TO authenticated; GRANT ALL ON public.voorraad_periode TO service_role; ALTER TABLE public.voorraad_periode ENABLE ROW LEVEL SECURITY;
CREATE POLICY proef_lezen ON public.voorraad_periode FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.voorraad_artikel a WHERE a.id=voorraad_artikel_id AND heeft_vestiging(auth.uid(),a.vestiging)));
CREATE TABLE public.leer_voorstel(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),vestiging text NOT NULL CHECK(vestiging IN ('West','Midsland')),onderwerp text NOT NULL,voorraad_artikel_id uuid REFERENCES public.voorraad_artikel(id),artikel_id uuid REFERENCES public.artikelen(id),soort text NOT NULL CHECK(soort IN ('verbruiksopslag_pct','onderzoeken','advies_controleren')),huidige_waarde numeric,voorgestelde_waarde numeric,onderbouwing jsonb NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','akkoord','afgewezen')),beoordeeld_door uuid,beoordeeld_op timestamptz,created_at timestamptz NOT NULL DEFAULT now(),bijgewerkt_op timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.leer_voorstel TO authenticated; GRANT UPDATE(status,beoordeeld_door,beoordeeld_op) ON public.leer_voorstel TO authenticated; GRANT ALL ON public.leer_voorstel TO service_role; ALTER TABLE public.leer_voorstel ENABLE ROW LEVEL SECURITY;
CREATE POLICY proef_lezen ON public.leer_voorstel FOR SELECT TO authenticated USING(heeft_vestiging(auth.uid(),vestiging));
CREATE POLICY proef_beoordelen ON public.leer_voorstel FOR UPDATE TO authenticated USING(heeft_vestiging(auth.uid(),vestiging) AND (has_role(auth.uid(),'owner') OR has_role(auth.uid(),'admin'))) WITH CHECK(heeft_vestiging(auth.uid(),vestiging) AND (has_role(auth.uid(),'owner') OR has_role(auth.uid(),'admin')));
CREATE UNIQUE INDEX leer_voorstel_een_open ON public.leer_voorstel(vestiging,onderwerp,soort) WHERE status='open';
COMMENT ON TABLE public.voorraad_artikel IS 'Voorraadproef: eigen vestiging; instellingen alleen owner/admin; geen automatisch bestellen.';
COMMENT ON TABLE public.voorraad_ontvangst_koppeling IS 'Ontvangstfactoren in teleenheden; ambigue bronnen niet kwantificeren.';
COMMENT ON TABLE public.voorraad_verbruik_koppeling IS 'Exacte Lightspeed product-id per vestiging en proefgroep; retouren meetellen.';
COMMENT ON TABLE public.voorraad_telling IS 'Blinde telling: server valideert plekken en totaal; tweede hertelling leidend; immutable voor client.';
COMMENT ON TABLE public.voorraad_correctie IS 'Alleen handmatige ownercorrecties; ochtend datum >= telling; sluit datum > telling.';
COMMENT ON TABLE public.advies_log IS 'Service-only advieslog; unieke vestiging/leverdag/artikel/methode inclusief NULL; geen orders.';
COMMENT ON TABLE public.voorraad_periode IS 'Opeenvolgende betrouwbare tellingen: begin+ontvangst+correcties-eind-kassa; momentafhankelijke [begin,eind).';
COMMENT ON TABLE public.leer_voorstel IS 'Alleen voorstellen; akkoord past nooit verbruiksopslag toe; beoordeling door owner/admin.';